import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ai-video-ads`,heroTitle:`Create video ads that convert in minutes`,heroSubtitle:`Perplexity Computer analyzes your brand, scripts high-converting video ads, and delivers ready-to-produce creative briefs — automatically.`,inputUrlCta:`Script my video ads`,inputUrlPlaceholder:`yourbrand.com`,inputUrlPrefill:`Go to {url} and perform a deep brand and product analysis — extract the brand voice, tone, visual identity, color palette, key products or services, value propositions, and target audience. Then create a complete AI video ad package: 1) Research top-performing video ad formats and hooks in this brand's industry. 2) Script 5 video ads in different formats — a 15-second hook ad, a 30-second product demo, a 60-second story-driven ad, a UGC-style testimonial script, and a problem-solution format. Each script should include scene-by-scene breakdowns with visual direction, on-screen text, voiceover copy, music/mood notes, and a strong CTA. 3) For each script, provide 3 hook variations for the opening 3 seconds. 4) Include a creative brief for each ad covering target platform (TikTok, Instagram Reels, YouTube, Facebook), aspect ratio, estimated production complexity, and casting notes. 5) Deliver a performance strategy doc with recommended targeting angles, A/B testing plan, and KPIs to track for each ad format. Package everything in a clean, organized format ready to hand to a video production team.`,heroOverlaySteps:[`Analyzing your brand voice, products, and target audience`,`Researching top-performing video ad formats in your industry`,`Scripting video ads with scene breakdowns and creative briefs`,`Five video ad scripts with hooks and production briefs — ready to produce`],generatingSteps:[`Visiting {url} to extract brand voice, products, visuals, and audience`,`Designing an agent to research winning video ad formats and script high-converting creatives`,`Configuring scene-by-scene breakdowns, hook variations, and platform-specific creative briefs`,`Setting up your performance strategy with targeting angles and A/B testing plans`],featureSectionTitle:`From URL to video ad scripts`,featureCardTitles:[`Connects to your marketing stack`,`Outputs you can produce`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Drive, Notion, Canva, Slack — Computer delivers your scripts, creative briefs, and performance plans straight into the tools you already use.`,`Scene-by-scene video scripts. Hook variations for the first 3 seconds. Platform-specific creative briefs. Casting and music notes. A/B testing plans with KPIs.`],capabilitySectionTitle:`Your creative team, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to production-ready video ad scripts.`,capabilityCards:[{title:`Brand Extraction`,description:`Computer can analyze your website — voice, visuals, products, and audience — to build a brand profile that informs every script it writes.`},{title:`Ad Scripting`,description:`Computer can write video ad scripts in multiple formats — hook ads, product demos, UGC-style, story-driven — each with scene breakdowns and voiceover copy.`},{title:`Hook Variations`,description:`Computer can generate multiple opening hooks per script — testing different angles, emotions, and patterns to maximize the first 3 seconds.`},{title:`Connect Your Tools`,description:`Computer can push scripts and briefs to Google Drive, Notion, Google Sheets, Canva, and Slack — keeping your production pipeline flowing.`},{title:`Learn & Improve`,description:`Computer can remember your past scripts, winning hooks, and brand guidelines across sessions — so every new batch builds on what works.`},{title:`Monitor & Refresh`,description:`Computer can track ad fatigue signals and trending formats — then alert you when it's time for fresh creative or new hook angles.`}]});export{t as default};
